package factories

import (
	"context"
	"database/sql"
	"fmt"
	"github.com/go-faker/faker/v4"
	"mortenvistisen/internal/storage"
	"mortenvistisen/models"
	"time"
)

// Factory declarations below are generated by Andurel.

type ArticleFactory struct {
	models.ArticleEntity
}

type ArticleOption func(*ArticleFactory)

func BuildArticle(opts ...ArticleOption) models.ArticleEntity {
	f := &ArticleFactory{
		ArticleEntity: models.ArticleEntity{
			FirstPublishedAt: sql.NullTime{Time: time.Now(), Valid: true},
			Published:        randomBool(),
			Title:            faker.Word(),
			Excerpt:          sql.NullString{String: faker.Word(), Valid: true},
			MetaTitle:        sql.NullString{String: faker.Word(), Valid: true},
			MetaDescription:  sql.NullString{String: faker.Word(), Valid: true},
			Slug:             faker.Word(),
			ImageLink:        sql.NullString{String: faker.Word(), Valid: true},
			ReadTime:         sql.NullInt32{Int32: randomInt(1, 1000, 100), Valid: true},
			Content:          sql.NullString{String: faker.Word(), Valid: true},
			MetaImageLink:    sql.NullString{String: faker.Word(), Valid: true},
		},
	}

	for _, opt := range opts {
		opt(f)
	}

	return f.ArticleEntity
}

func CreateArticle(ctx context.Context, exec storage.Executor, opts ...ArticleOption) (models.ArticleEntity, error) {
	built := BuildArticle(opts...)

	entity := models.ArticleEntity{
		ID:               built.ID,
		CreatedAt:        time.Now(),
		UpdatedAt:        time.Now(),
		FirstPublishedAt: built.FirstPublishedAt,
		Published:        built.Published,
		Title:            built.Title,
		Excerpt:          built.Excerpt,
		MetaTitle:        built.MetaTitle,
		MetaDescription:  built.MetaDescription,
		Slug:             built.Slug,
		ImageLink:        built.ImageLink,
		ReadTime:         built.ReadTime,
		Content:          built.Content,
		MetaImageLink:    built.MetaImageLink,
	}

	if err := exec.NewInsert().Model(&entity).Returning("*").Scan(ctx); err != nil {
		return models.ArticleEntity{}, err
	}

	return entity, nil
}

func CreateArticles(ctx context.Context, exec storage.Executor, count int, opts ...ArticleOption) ([]models.ArticleEntity, error) {
	articles := make([]models.ArticleEntity, 0, count)

	for i := 0; i < count; i++ {
		entity, err := CreateArticle(ctx, exec, opts...)
		if err != nil {
			return nil, fmt.Errorf("failed to create article %d: %w", i+1, err)
		}
		articles = append(articles, entity)
	}

	return articles, nil
}

